local Component=require(script.Parent.Parent.Base.Component)
return function(ctx,nodes,onSelect) local list=Instance.new("ScrollingFrame",ctx.Parent);list.Name="TreeView";list.Size=UDim2.new(1,0,0,220);list.BackgroundTransparency=1;list.BorderSizePixel=0;list.ScrollBarThickness=4;local lay=Instance.new("UIListLayout",list);local function add(nodes,depth)for _,node in ipairs(nodes or {})do local b=Instance.new("TextButton",list);b.Size=UDim2.new(1,0,0,30);b.BackgroundTransparency=1;b.Text=string.rep("  ",depth or 0)..tostring(node.Name or node[1]);b.TextColor3=ctx.Theme:Get("Text");b.Font=Enum.Font.Gotham;b.TextSize=13;b.TextXAlignment=Enum.TextXAlignment.Left;ctx.Input:BindPress(b,function()if onSelect then onSelect(node)end end);if node.Children then add(node.Children,(depth or 0)+1)end end end;add(nodes,0);return Component.new(list,ctx) end
